import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"47. 命令行参数（argc、argv）","description":"The Little Book of C 中文版 — 47. 命令行参数（argc、argv）","frontmatter":{"title":"47. 命令行参数（argc、argv）","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","05-输入输出与文件","中文"],"description":"The Little Book of C 中文版 — 47. 命令行参数（argc、argv）","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":47,"sidebarWeight":47,"alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/047-Command-Line Arguments (argc, argv)","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/047-Command-Line Arguments (argc, argv)"},"headers":[],"relativePath":"posts/c教程/zh-CN/05-输入输出与文件/047-Command-Line Arguments (argc, argv).md","filePath":"posts/c教程/zh-CN/05-输入输出与文件/047-Command-Line Arguments (argc, argv).md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/05-输入输出与文件/047-Command-Line Arguments (argc, argv).md"};function i(l,a,c,o,d,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/05-Input Output and Files/047-Command-Line Arguments (argc, argv))</p><p>每个C程序都可以直接从命令行接收输入，不<code>scanf</code>， 不<code>fgets</code>，只是运行可执行文件时传递的参数。这就是专业的 C 工具（例如<code>gcc</code>,<code>ls</code>， 和<code>grep</code>) 接收文件名、选项和标志。</p><h4 id="函数签名" tabindex="-1">函数签名 <a class="header-anchor" href="#函数签名" aria-label="Permalink to &quot;函数签名&quot;">​</a></h4><p>你的<code>main</code>函数可以带两个参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int main(int argc, char *argv[])</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>意义</th></tr></thead><tbody><tr><td><code>argc</code></td><td>参数计数（命令行参数的数量）</td></tr><tr><td><code>argv</code></td><td>参数向量（C 字符串数组，每个参数）</td></tr></tbody></table><p><code>argv[0]</code>是程序名称本身，并且<code>argv[1]</code>接下来是用户提供的参数。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello world test</span></span></code></pre></div><p>然后：</p><p>-<code>argc == 3</code> -<code>argv[0] = &quot;./hello&quot;</code> -<code>argv[1] = &quot;world&quot;</code> -<code>argv[2] = &quot;test&quot;</code></p><h4 id="小代码-打印命令行参数" tabindex="-1">小代码：打印命令行参数 <a class="header-anchor" href="#小代码-打印命令行参数" aria-label="Permalink to &quot;小代码：打印命令行参数&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    printf(&quot;Argument count: %d\\n&quot;, argc);</span></span>
<span class="line"><span>    for (int i = 0; i &lt; argc; i++)</span></span>
<span class="line"><span>        printf(&quot;argv[%d] = %s\\n&quot;, i, argv[i]);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./args foo bar 123</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Argument count: 4</span></span>
<span class="line"><span>argv[0] = ./args</span></span>
<span class="line"><span>argv[1] = foo</span></span>
<span class="line"><span>argv[2] = bar</span></span>
<span class="line"><span>argv[3] = 123</span></span></code></pre></div><h4 id="检查是否缺少参数" tabindex="-1">检查是否缺少参数 <a class="header-anchor" href="#检查是否缺少参数" aria-label="Permalink to &quot;检查是否缺少参数&quot;">​</a></h4><p>如果您的程序需要参数，请检查<code>argc</code>在访问它们之前。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc &lt; 2) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;filename&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Opening file: %s\\n&quot;, argv[1]);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./fileop</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: ./fileop &lt;filename&gt;</span></span></code></pre></div><p>再次运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./fileop data.txt</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Opening file: data.txt</span></span></code></pre></div><h4 id="将字符串参数转换为数字" tabindex="-1">将字符串参数转换为数字 <a class="header-anchor" href="#将字符串参数转换为数字" aria-label="Permalink to &quot;将字符串参数转换为数字&quot;">​</a></h4><p>所有命令行参数都是字符串。要将它们用作数字，请使用以下命令进行转换：</p><p>-<code>atoi()</code>– 字符串转整数 -<code>atof()</code>– 浮动字符串 -<code>strtol()</code>/<code>strtod()</code>– 更安全、更灵活的替代方案</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc != 3) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;a&gt; &lt;b&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    int a = atoi(argv[1]);</span></span>
<span class="line"><span>    int b = atoi(argv[2]);</span></span>
<span class="line"><span>    printf(&quot;%d + %d = %d\\n&quot;, a, b, a + b);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./sum 10 25</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10 + 25 = 35</span></span></code></pre></div><h4 id="处理选项-标志" tabindex="-1">处理选项（标志） <a class="header-anchor" href="#处理选项-标志" aria-label="Permalink to &quot;处理选项（标志）&quot;">​</a></h4><p>您可以构建简单的命令行工具来手动处理选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    int verbose = 0;</span></span>
<span class="line"><span>    for (int i = 1; i &lt; argc; i++) {</span></span>
<span class="line"><span>        if (strcmp(argv[i], &quot;-v&quot;) == 0)</span></span>
<span class="line"><span>            verbose = 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if (verbose)</span></span>
<span class="line"><span>        printf(&quot;Verbose mode on\\n&quot;);</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        printf(&quot;Run quietly\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./tool -v</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Verbose mode on</span></span></code></pre></div><h4 id="tiny-code-迷你文件回显工具" tabindex="-1">Tiny Code：迷你文件回显工具 <a class="header-anchor" href="#tiny-code-迷你文件回显工具" aria-label="Permalink to &quot;Tiny Code：迷你文件回显工具&quot;">​</a></h4><p>该程序打印作为参数传递的文件的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc != 2) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;file&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    FILE *fp = fopen(argv[1], &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Error&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[128];</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, buf);</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./echo mytext.txt</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p><code>argc</code>和<code>argv</code>使您的 C 程序可编写脚本且可组合：</p><ul><li>从命令行自动执行任务</li><li>与 shell 脚本或管道集成</li><li>处理多个输入文件</li><li>实施命令行标志和选项</li></ul><p>每个现实世界的 C 实用程序，来自<code>ls</code>到<code>gcc</code>，取决于此模式。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>编写一个程序，获取整数列表并打印它们的总和。</p><p>添加一个<code>-r</code>标志来反转打印参数的顺序。</p><p>构建一个“问候”工具：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./greet Alice Bob Charlie</span></span></code></pre></div><p>→<code>Hello, Alice! Hello, Bob! Hello, Charlie!</code></p><p>编写一个“比较”工具来检查两个文件名是否相同。</p><p>结合<code>argc</code>和文件 I/O：将一个文件复制到另一个文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./copy source.txt dest.txt</span></span></code></pre></div><p>通过命令行参数，您的 C 程序可以从静态练习发展为灵活的实际工具。接下来，您将探索读取配置文件，这是一种让您的程序自动适应而无需重新编译的强大方法。</p>`,63)])])}const u=s(t,[["render",i]]);export{h as __pageData,u as default};
